// memoryMigrationFinding names one derived artifact whose schema is not
// current and the action migrate takes.
type memoryMigrationFinding struct {
	Path   string `json:"path"`
	State  string `json:"state"`
	Action string `json:"action"`
}

type memoryMigrationProgress struct {
	SchemaVersion int       `json:"schema_version"`
	OperationID   string    `json:"operation_id"`
	StartedAt     time.Time `json:"started_at"`
	Completed     []string  `json:"completed"`
}

func loadMemoryMigrationProgress(brainDir string) (memoryMigrationProgress, bool, error) {
	data, present, err := readMemoryStateFile(brainDir, memoryMigrationProgressRel, "migration progress", maxManifestBytes)
	if err != nil {
		return memoryMigrationProgress{}, present, err
	}
	if !present {
		return memoryMigrationProgress{}, false, nil
	}
	var header struct {
		SchemaVersion int `json:"schema_version"`
	}
	if err := json.Unmarshal(data, &header); err != nil {
		return memoryMigrationProgress{}, true, fmt.Errorf("%s: decode migration progress header: %w", memoryErrStateCorrupt, err)
	}
	if header.SchemaVersion > 1 {
		return memoryMigrationProgress{}, true, fmt.Errorf("%s: migration progress schema version %d is newer than supported version 1", memoryErrUnsupportedVersion, header.SchemaVersion)
	}
	var progress memoryMigrationProgress
	if _, err := decodeVersionedJSONBody(data, &progress, false); err != nil {
		if errors.Is(err, errTrailingJSONData) {
			return memoryMigrationProgress{}, true, fmt.Errorf("%s: migration progress has trailing JSON data", memoryErrStateCorrupt)
		}
		return memoryMigrationProgress{}, true, fmt.Errorf("%s: decode migration progress: %w", memoryErrStateCorrupt, err)
	}
	if progress.SchemaVersion != 1 || !strings.HasPrefix(progress.OperationID, "op:") || progress.StartedAt.IsZero() || len(progress.Completed) > memoryStateInventoryMaxEntries {
		return memoryMigrationProgress{}, true, fmt.Errorf("%s: migration progress has invalid identity or bounds", memoryErrStateCorrupt)
	}
	seen := make(map[string]bool, len(progress.Completed))
	for _, rel := range progress.Completed {
		clean, cleanErr := cleanBrainRelativePath(filepath.ToSlash(strings.TrimSpace(rel)))
		if cleanErr != nil || filepath.ToSlash(clean) != rel || seen[rel] {
			return memoryMigrationProgress{}, true, fmt.Errorf("%s: migration progress contains an invalid completed path", memoryErrStateCorrupt)
		}
		seen[rel] = true
	}
	return progress, true, nil
}

func saveMemoryMigrationProgress(brainDir string, progress memoryMigrationProgress) error {
	data, err := json.MarshalIndent(progress, "", "  ")
	if err != nil {
		return err
	}
	return writeBrainRelativeFileAtomic(brainDir, memoryMigrationProgressRel, append(data, '\n'), 0o600)
}

var saveMemoryMigrationProgressForAdmin = saveMemoryMigrationProgress

// detectMemoryMigrations inspects derived schema versions. Disposable formats
// migrate by rebuilding beside the old artifact and atomically switching
// (that is exactly what the existing atomic writers do); unknown NEWER
// versions are read-only errors that name the required action.
func detectMemoryMigrations(brainDir string, source *historySourceManifest) []memoryMigrationFinding {
	var findings []memoryMigrationFinding
	if _, present, err := loadMemoryMigrationProgress(brainDir); err != nil {
		state := memoryErrorCode(err)
		action := "inspect and restore the migration progress file before resuming"
		if state == memoryErrUnsupportedVersion {
			action = "upgrade the binary; this newer migration progress remains read-only"
		}
		findings = append(findings, memoryMigrationFinding{Path: memoryMigrationProgressRel, State: state, Action: action})
	} else if present {
		// Valid progress is intentionally not a migration finding. The status
		// surface exposes it separately; --resume revalidates current artifacts
		// instead of trusting completed path names as proof.
	}
	if _, present, err := loadMemoryVectorProgress(brainDir); err != nil {
		state := memoryErrorCode(err)
		action := "delete and rebuild this disposable vector progress state from the current history generation"
		switch state {
		case memoryErrUnsupportedVersion:
			action = "upgrade the binary; this newer vector progress state remains read-only"
		case memoryErrStateUnsafe:
			action = "inspect the unsafe vector progress path; no file is removed automatically"
		}
		findings = append(findings, memoryMigrationFinding{Path: memoryVectorProgressRel, State: state, Action: action})
	} else if present {
		// Current vector progress is operational status, not a migration.
	}
	if source != nil {
		path := strings.TrimSpace(source.IndexPath)
		if path == "" {
			path = historyIndexPath
		}
		if source.IndexDigest == "" && validHistoryGenerationArtifactPath(path, historyIndexFileName) {
			findings = append(findings, memoryMigrationFinding{Path: path, State: memoryErrMigrationRequired, Action: "rebuild the generation and publish its manifest content digest (full refresh)"})
		} else if _, err := loadBrainHistoryIndex(brainDir, source); err != nil {
			findings = append(findings, memoryMigrationFinding{Path: path, State: memoryErrStateCorrupt, Action: "rebuild the disposable history projection from canonical sessions"})
		} else if source.IndexDigest == "" {
			findings = append(findings, memoryMigrationFinding{Path: path, State: memoryErrMigrationRequired, Action: "publish a manifest-committed index content digest (full refresh)"})
		}
	}
	if overlay, state := loadHistoryShortTermRaw(brainDir); state == shortTermStateCurrent {
		switch {
		case overlay.Version > historyShortTermVersion:
			findings = append(findings, memoryMigrationFinding{Path: historyShortTermPath, State: memoryErrUnsupportedVersion, Action: "newer-version overlay is read-only for this binary; upgrade the binary or delete the file to rebuild"})
		case overlay.Version < historyShortTermVersion || overlay.ReconcilerVersion != historyShortTermReconcilerVersion:
			findings = append(findings, memoryMigrationFinding{Path: historyShortTermPath, State: memoryErrMigrationRequired, Action: "rebuild the overlay (refresh delta)"})
		}
	} else if state == shortTermStateCorrupt {
		findings = append(findings, memoryMigrationFinding{Path: historyShortTermPath, State: memoryErrStateCorrupt, Action: "repair or rebuild the disposable overlay from canonical sessions"})
	} else if state == shortTermStateUnsupported {
		findings = append(findings, memoryMigrationFinding{Path: historyShortTermPath, State: memoryErrUnsupportedVersion, Action: "newer-version overlay is read-only for this binary; upgrade the binary"})
	}
	if source != nil {
		receiptPath := filepath.ToSlash(strings.TrimSpace(source.ProjectionStatePath))
		if receiptPath == "" {
			receiptPath = projectionStateRel
		}
		if source.ProjectionStateDigest == "" {
			findings = append(findings, memoryMigrationFinding{Path: receiptPath, State: memoryErrMigrationRequired, Action: "publish projection receipts (full refresh)"})
		} else {
			_, receiptState, receiptErr := loadProjectionStateChecked(brainDir, source)
			if receiptState != projectionStateCurrent {
				state := memoryErrStateCorrupt
				action := "rebuild the disposable projection receipts from canonical sessions"
				switch receiptState {
				case projectionStateUnsupported:
					state = memoryErrUnsupportedVersion
					action = "upgrade the binary; this newer projection receipt remains read-only"
				case projectionStateUnsafe:
					state = memoryErrStateUnsafe
					action = "inspect the unsafe projection receipt path; no file is removed automatically"
				case projectionStateStale:
					state = memoryErrSourceStale
				}
				if receiptErr != nil {
					state = memoryErrorCode(receiptErr)
				}
				findings = append(findings, memoryMigrationFinding{Path: receiptPath, State: state, Action: action})
			}
		}
	}
	_, configState, configErr := loadMemoryConfigChecked(brainDir)
	if configErr != nil {
		state := string(configState)
		findings = append(findings, memoryMigrationFinding{Path: memoryConfigRel, State: state, Action: "inspect and restore the content-free feature selection; configuration is not deleted automatically"})
	}
	abstractInventory := loadSessionAbstractInventory(brainDir)

package cli

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
)

// readBrainManifestFile decodes the canonical manifest without a byte ceiling.
// It uses the same checked descriptor as bounded state readers, without needing
// the source repository or Git. encoding/json buffers a whole JSON value and
// the manifest is materialized in memory: this is NOT a bounded-memory reader.
// Rewinding this descriptor (never reopening the path) preserves schema-first
// checks and tolerant reads versus strict rewrites, including unknown fields.
func readBrainManifestFile(brainDir string, tolerateUnknown bool) (*exportManifest, int, bool, bool, error) {
	f, present, err := openMemoryStateFileExpected(brainDir, exportManifestFileName, "brain manifest", nil)
	if err != nil {
		return nil, 0, false, present, fmt.Errorf("read brain manifest: %w", err)
	}
	if !present {
		return &exportManifest{SchemaVersion: brainManifestSchemaVersion}, 0, false, false, nil
	}
	defer f.Close()
	manifest, version, dropped, err := decodeBrainManifestFile(f, tolerateUnknown)
	return manifest, version, dropped, true, err
}

func decodeManifestPass(f *os.File, out any, strict bool) error {
	if _, err := f.Seek(0, io.SeekStart); err != nil {
		return err
	}
	decoder := json.NewDecoder(f)
	if strict {
		decoder.DisallowUnknownFields()
	}
	if err := decoder.Decode(out); err != nil {
		return err
	}
	if err := decoder.Decode(&struct{}{}); !errors.Is(err, io.EOF) {
		return errTrailingJSONData
	}
	return nil
}

func decodeBrainManifestFile(f *os.File, tolerateUnknown bool) (*exportManifest, int, bool, error) {
	var header struct {
		SchemaVersion int `json:"schema_version"`
	}
	if err := decodeManifestPass(f, &header, false); err != nil {
		return nil, 0, false, fmt.Errorf("parse brain manifest: %s: brain manifest cannot be parsed: %w", memoryErrStateCorrupt, err)
	}
	version := header.SchemaVersion
	if version > brainManifestSchemaVersion {
		return nil, version, false, fmt.Errorf("%s: brain manifest schema version %d is newer than supported version %d", memoryErrUnsupportedVersion, version, brainManifestSchemaVersion)
	}
	var manifest exportManifest
	err := decodeManifestPass(f, &manifest, true)
	dropped := false
	if tolerateUnknown && isUnknownFieldError(err) {
		manifest = exportManifest{}
		err = decodeManifestPass(f, &manifest, false)
		dropped = err == nil
	}
	if err != nil {
		// An unknown field is not damage, and saying "cannot be parsed" sends
		// the reader looking for corruption that is not there. The manifest is
		// entirely readable; a WRITER is refusing it, because re-encoding from
		// a struct that never saw the field would erase what another build
		// recorded. Readers pass tolerateUnknown and are unaffected.
		//
		// Observed cost of the old wording: a component sat failed for four
		// days reporting memory_state_corrupt, while the manifest was fine and
		// the condition had already gone away.
		//
		// The error CODE stays memory_state_corrupt deliberately. It is part of
		// the maintenance taxonomy with many consumers, so retyping this case
		// is a contract change for a human to make, not a side effect of
		// improving a sentence.
		if !tolerateUnknown && isUnknownFieldError(err) {
			return nil, version, false, fmt.Errorf(
				"parse brain manifest: %s: brain manifest carries a field this build does not know (%w); "+
					"the file is readable and is NOT damaged, but a writer will not rewrite it and silently drop that field. "+
					"Use a build that knows the field, or let a read-only command run instead",
				memoryErrStateCorrupt, err)
		}
		return nil, version, false, fmt.Errorf("parse brain manifest: %s: brain manifest cannot be parsed: %w", memoryErrStateCorrupt, err)
	}
	if version < brainManifestMinSchemaVersion {
		return nil, version, false, fmt.Errorf("%s: brain manifest declares schema version %d, older than the first supported version %d", memoryErrUnsupportedVersion, version, brainManifestMinSchemaVersion)
	}
	normalizeBrainManifest(&manifest)
	return &manifest, version, dropped, nil
}

}

// loadBrainManifest reads the manifest for the callers that only consume it —
// status, doctor, the MCP surface, the memory worker, distillation, search.
//
// It tolerates fields it does not declare. Manifest fields are added and retired
// without a schema bump (history_coverage.checkpointed_unexported_commits was
// retired at version 3), so every manifest written before such a change carries
// a field a later build has never heard of. Rejecting those bytes reported the
// whole brain as memory_state_corrupt: all sources off, no facts, and the memory
// worker failing on its retry loop indefinitely, for state that was merely
// written by a different build and is entirely readable.
//
// Writers must not be this forgiving — see loadBrainManifestForReplace.
func loadBrainManifest(outputDir string) (*exportManifest, error) {
	manifest, _, err := readBrainManifest(outputDir, true)
	return manifest, err
}

// loadBrainManifestForReplace reads the manifest on behalf of a writer about to
// overwrite it, and refuses fields it cannot round-trip: re-encoding from a
// struct that never saw them erases what another build recorded. Availability is
// the reader's concern; not destroying state is this one's.
func loadBrainManifestForReplace(outputDir string) (*exportManifest, error) {
	manifest, _, err := readBrainManifest(outputDir, false)
	// NOT isUnknownFieldError: that matches on a PREFIX, and by the time the
	// error reaches here it has been wrapped ("parse brain manifest: ..."), so
	// the prefix never matches and the remedy was silently never attached.
	if errRetiredManifestField(err) {
		// Durable, and the bare decoder error says none of this. A field that
		// was RETIRED without a schema bump leaves every manifest written by
		// the older build unwritable by this one -- for ever, because nothing
		// in the normal path rewrites it. On this machine that silently drove
		// a two-hour relaunch chain per repository, with a live sleeping
		// process per retry, and the worker log recorded only "prepass_failed".
		return manifest, errors.New(retiredManifestFieldMessage(err))
	}
	return manifest, err
}

// errRetiredManifestField reports a manifest a writer cannot round-trip because
// it carries a field this build no longer declares.
//
// It is a DURABLE condition: no amount of retrying changes the bytes on disk,
// so a relaunch chain spends two hours and ends exactly where it started.
// retiredManifestRemedy is the one wording, so the "already said it" check
// below cannot drift from the thing it is checking for.
// A func, not a const: the spelling depends on how the reader reached this
// binary, which is only knowable at call time.
func retiredManifestRemedy() string {
	return "; this manifest carries a field this build retired, so it cannot be rewritten without erasing what another build recorded -- rebuild it with `" + brainInvocation(os.LookupEnv, "refresh") + " --force`"
}

// retiredManifestFieldMessage states the failure AND what to do about it.
//
// The remedy has to be attached here rather than at the read, because the
// manifest is read through several paths and only some of them wrap the error.
// Measured: the delta-export path reported the bare decoder error, so the one
// line a reader actually saw named a JSON field and no action at all.
func retiredManifestFieldMessage(err error) string {
	if err == nil {
		return ""
	}
	msg := err.Error()
	// Idempotent. loadBrainManifestForReplace already attaches this remedy, and
	// the worker then asks for the message again -- appending unconditionally
	// printed the whole explanation TWICE. Caught by weakening: deleting this
	// function's retired-field branch made the output better, which is only
	// possible if the branch was doing harm.
	if strings.Contains(msg, retiredManifestRemedy()) {
		return msg
	}
	return msg + retiredManifestRemedy()
}

